moduleData.comboCode:
combo AlwaysRun {
    set_val(PS5_CROSS, 100)
    wait(50)
    set_val(PS5_CROSS, 0)
    wait(50)
}

moduleData.mainCode:
if (isqrt((get_val(PS5_LX) * get_val(PS5_LX)) + (get_val(PS5_LY) * get_val(PS5_LY))) > AutoRunThreshold) {
    AutoRunStatus = 0;
    FlowRedraw = TRUE;
}
set_val(PS5_LY, -100);
set_val(PS5_CROSS, 100);

if (get_val(PS5_CROSS)) { ButtonToMash = PS5_CROSS; combo_run(MashCombo); }
else if (get_val(PS5_TRIANGLE)) { ButtonToMash = PS5_TRIANGLE; combo_run(MashCombo); }
else if (get_val(PS5_CIRCLE)) { ButtonToMash = PS5_CIRCLE; combo_run(MashCombo); }
else if (get_val(PS5_SQUARE)) { ButtonToMash = PS5_SQUARE; combo_run(MashCombo); }
else combo_stop(MashCombo);

moduleData.comboCode:
combo MashCombo {
    set_val(ButtonToMash, 100);
    wait(50);
    set_val(ButtonToMash, 0);
    wait(50);
}

combo RightStickCircleReeling {
    // 0° - Right
    set_val(PS5_RX, 100);
    set_val(PS5_RY, 0);
    wait(10);
    // 22.5°
    set_val(PS5_RX, 92);
    set_val(PS5_RY, 38);
    wait(10);
    // 45°
    set_val(PS5_RX, 71);
    set_val(PS5_RY, 71);
    wait(10);
    // 67.5°
    set_val(PS5_RX, 38);
    set_val(PS5_RY, 92);
    wait(10);
    // 90° - Down
    set_val(PS5_RX, 0);
    set_val(PS5_RY, 100);
    wait(10);
    // 112.5°
    set_val(PS5_RX, -38);
    set_val(PS5_RY, 92);
    wait(10);
    // 135°
    set_val(PS5_RX, -71);
    set_val(PS5_RY, 71);
    wait(10);
    // 157.5°
    set_val(PS5_RX, -92);
    set_val(PS5_RY, 38);
    wait(10);
    // 180° - Left
    set_val(PS5_RX, -100);
    set_val(PS5_RY, 0);
    wait(10);
    // 202.5°
    set_val(PS5_RX, -92);
    set_val(PS5_RY, -38);
    wait(10);
    // 225°
    set_val(PS5_RX, -71);
    set_val(PS5_RY, -71);
    wait(10);
    // 247.5°
    set_val(PS5_RX, -38);
    set_val(PS5_RY, -92);
    wait(10);
    // 270° - Up
    set_val(PS5_RX, 0);
    set_val(PS5_RY, -100);
    wait(10);
    // 292.5°
    set_val(PS5_RX, 38);
    set_val(PS5_RY, -92);
    wait(10);
    // 315°
    set_val(PS5_RX, 71);
    set_val(PS5_RY, -71);
    wait(10);
    // 337.5°
    set_val(PS5_RX, 92);
    set_val(PS5_RY, -38);
    wait(10);
}
